pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {StaxLPStaking} from "../src/StaxLPStaking.sol";

contract InvMutTest is Test {
    StaxLPStaking c;
    function setUp() public { c = new StaxLPStaking(address(this), address(this)); }
    function testFuzz_property(address nonOwner, address newOwner) public {
        vm.assume(nonOwner != address(this));
        vm.assume(nonOwner != address(0));
        vm.assume(newOwner != address(0));
        address ownerBefore = c.owner();
        vm.prank(nonOwner);
        try c.transferOwnership(newOwner) {} catch {}
        address ownerAfter = c.owner();
        assertTrue(ownerAfter == ownerBefore);
    }
}
